export function getCharactersUpToChapter(slug: string, chapter: number): Character[] {
  const chars = bookCharacters[slug] || [];
  return chars.filter(c => c.firstChapter <= chapter);
}

export function getFilteredCharacters(slug: string, chapter: number): Character[] {
  const chars = getCharactersUpToChapter(slug, chapter);
  return chars.map(c => ({
    ...c,
    connections: c.connections?.filter(conn => conn.chapter <= chapter),
  }));
}

export function getChaptersUpTo(slug: string, chapter: number): ChapterInfo[] {
  const chs = bookChapters[slug] || [];
  return chs.filter(c => c.number <= chapter);
}

export function getThemesForBook(slug: string): string[] {
  return bookThemes[slug] || ['Character Development', 'Plot', 'Setting', 'Conflict', 'Resolution'];
}
